export const FUND_PAGE_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"referrer\" content=\"no-referrer\">\n<title>Fund your agent</title>\n<!--\n  Funding page for the aztec-x402 skill. One self-contained file, no external\n  scripts. Two ways it is opened:\n\n  - local:  served by `aztec-x402 fund` at http://127.0.0.1:<port>/?t=<token>;\n            reads the funding plan from the CLI and reports the deposit back.\n  - hosted: a static copy opened as <url>#<plan>; the plan travels in the URL\n            fragment, which browsers never send to the host. The CLI finds the\n            deposit by watching L1, so nothing reports back.\n\n  The plan holds owner-independent calldata. This page only fills in the\n  connected account and asks the wallet to sign. The claim secret never\n  leaves the agent; the plan carries only its hash.\n-->\n<style>\n  :root {\n    --bg: #f7f7f5; --card: #ffffff; --text: #1b1b1f; --muted: #62636b; --line: #e3e3e0;\n    --accent: #3a4fd8; --accent-text: #ffffff; --ok: #1d7f4e; --warn: #9a5b00; --err: #b3261e;\n    --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  }\n  @media (prefers-color-scheme: dark) {\n    :root {\n      --bg: #121316; --card: #1b1c20; --text: #ececf0; --muted: #a0a1aa; --line: #2c2d33;\n      --accent: #8c9bff; --accent-text: #0d0f1a; --ok: #5cd39a; --warn: #f0b45c; --err: #ff8a80;\n    }\n  }\n  * { box-sizing: border-box; }\n  body { margin: 0; background: var(--bg); color: var(--text);\n    font: 15px/1.5 system-ui, -apple-system, \"Segoe UI\", sans-serif; }\n  main { max-width: 640px; margin: 0 auto; padding: 32px 16px 64px; }\n  h1 { font-size: 22px; margin: 0 0 4px; }\n  .sub { color: var(--muted); margin: 0 0 24px; }\n  .card { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 20px; margin-bottom: 16px; }\n  .card h2 { font-size: 15px; margin: 0 0 12px; }\n  dl { display: grid; grid-template-columns: max-content 1fr; gap: 6px 16px; margin: 0; }\n  dt { color: var(--muted); }\n  dd { margin: 0; min-width: 0; }\n  .mono { font-family: var(--mono); font-size: 13px; overflow-wrap: anywhere; }\n  .note { color: var(--muted); font-size: 13px; margin: 12px 0 0; }\n  button { font: inherit; font-weight: 600; border: 0; border-radius: 8px; padding: 10px 16px;\n    background: var(--accent); color: var(--accent-text); cursor: pointer; }\n  button:disabled { opacity: .5; cursor: default; }\n  ol.steps { list-style: none; padding: 0; margin: 0; }\n  ol.steps li { display: flex; gap: 12px; padding: 10px 0; border-top: 1px solid var(--line); }\n  ol.steps li:first-child { border-top: 0; }\n  .dot { flex: none; width: 22px; height: 22px; border-radius: 50%; border: 2px solid var(--line);\n    display: grid; place-items: center; font-size: 12px; margin-top: 1px; }\n  li.active .dot { border-color: var(--accent); color: var(--accent); }\n  li.done .dot { border-color: var(--ok); background: var(--ok); color: var(--card); }\n  li.failed .dot { border-color: var(--err); color: var(--err); }\n  li .label { flex: 1; min-width: 0; }\n  li .detail { color: var(--muted); font-size: 13px; }\n  .status { margin-top: 12px; font-weight: 600; }\n  .status.ok { color: var(--ok); } .status.err { color: var(--err); } .status.warn { color: var(--warn); }\n  a { color: var(--accent); }\n</style>\n</head>\n<body>\n<main>\n  <h1>Fund your agent</h1>\n  <p class=\"sub\" id=\"sub\">Loading…</p>\n\n  <section class=\"card\" id=\"deposit-card\" hidden>\n    <h2>Deposit</h2>\n    <dl id=\"facts\"></dl>\n    <p class=\"note\" id=\"privacy\"></p>\n  </section>\n\n  <section class=\"card\">\n    <h2>Steps</h2>\n    <ol class=\"steps\" id=\"steps\"></ol>\n    <div style=\"margin-top:16px\"><button id=\"go\" disabled>Connect wallet</button></div>\n    <div class=\"status\" id=\"status\" role=\"status\" aria-live=\"polite\"></div>\n  </section>\n</main>\n<script>\n\"use strict\";\nconst $ = (id) => document.getElementById(id);\nconst esc = (s) => String(s).replace(/[&<>\"]/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" }[c]));\nconst short = (a) => (a ? a.slice(0, 10) + \"…\" + a.slice(-8) : \"\");\nconst sleep = (ms) => new Promise((r) => setTimeout(r, ms));\n\nconst TOKEN = new URLSearchParams(location.search).get(\"t\");\nconst FRAGMENT = location.hash.slice(1);\nconst MODE = TOKEN ? \"local\" : FRAGMENT ? \"hosted\" : \"none\";\n\nlet plan;\nlet phase = \"signing\";\nlet l2Balance;\nlet serverError;\nlet owner;\nlet submitted = false;\nconst txStatus = {};\n\nfunction setStatus(text, kind) {\n  const el = $(\"status\");\n  el.textContent = text || \"\";\n  el.className = \"status \" + (kind || \"\");\n}\n\nasync function api(path, body) {\n  const res = await fetch(path + \"?t=\" + encodeURIComponent(TOKEN), body\n    ? { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify(body) }\n    : {});\n  const json = await res.json();\n  if (!res.ok) throw new Error(json.error || res.statusText);\n  return json;\n}\n\nfunction decodePlan(fragment) {\n  let b64 = fragment.replace(/-/g, \"+\").replace(/_/g, \"/\");\n  while (b64.length % 4) b64 += \"=\";\n  const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));\n  return JSON.parse(new TextDecoder().decode(bytes));\n}\n\nconst ADDRESS = /^0x[0-9a-fA-F]{40}$/;\nconst CALLDATA = /^0x([0-9a-fA-F]|\\{owner\\})*$/;\n\nfunction checkPlan(p) {\n  const fail = (what) => { throw new Error(\"This funding link is malformed (\" + what + \"). Ask your agent for a new one.\"); };\n  if (!p || p.v !== 1) fail(\"version\");\n  if (!/^0x[0-9a-fA-F]{64}$/.test(p.agent)) fail(\"agent address\");\n  if (!Number.isInteger(p.l1ChainId)) fail(\"chain\");\n  if (!ADDRESS.test(p.portal)) fail(\"portal\");\n  if (!Array.isArray(p.steps) || p.steps.length === 0 || p.steps.length > 10) fail(\"steps\");\n  for (const s of p.steps) {\n    if (!ADDRESS.test(s.to) || !CALLDATA.test(s.data)) fail(\"step \" + s.id);\n    if (s.skipIf && (!ADDRESS.test(s.skipIf.to) || !CALLDATA.test(s.skipIf.data) || !/^\\d+$/.test(s.skipIf.gte))) fail(\"step \" + s.id);\n  }\n  return p;\n}\n\nfunction eth(method, params) {\n  return window.ethereum.request({ method, params });\n}\n\nfunction fill(data) {\n  return data.split(\"{owner}\").join(owner.slice(2).toLowerCase().padStart(64, \"0\"));\n}\n\nasync function satisfied(step) {\n  if (!step.skipIf) return false;\n  const result = await eth(\"eth_call\", [{ to: step.skipIf.to, data: fill(step.skipIf.data) }, \"latest\"]);\n  return BigInt(!result || result === \"0x\" ? 0 : result) >= BigInt(step.skipIf.gte);\n}\n\n/** Wallets sometimes pick a stale nonce right after the previous tx; a fresh signature fixes it. */\nasync function sendWithRetry(step) {\n  for (let attempt = 1; ; attempt++) {\n    try {\n      return await eth(\"eth_sendTransaction\", [{ from: owner, to: step.to, data: fill(step.data) }]);\n    } catch (e) {\n      const message = (e && e.message) || String(e);\n      if (attempt >= 3 || !/nonce too low|nonce has already been used/i.test(message)) throw e;\n      txStatus[step.id] = { state: \"active\", text: \"Wallet used a stale nonce — please sign again…\" };\n      renderSteps();\n      await sleep(4000);\n    }\n  }\n}\n\nasync function waitReceipt(hash) {\n  for (;;) {\n    const r = await eth(\"eth_getTransactionReceipt\", [hash]);\n    if (r) return r;\n    await sleep(3000);\n  }\n}\n\nfunction renderFacts() {\n  $(\"deposit-card\").hidden = false;\n  $(\"sub\").textContent = \"Sign a deposit on \" + plan.l1ChainName + \" with your browser wallet. Your agent then claims it on Aztec \" + plan.network + \".\";\n  $(\"facts\").innerHTML = [\n    [\"Agent (Aztec)\", '<span class=\"mono\">' + esc(plan.agent) + \"</span>\"],\n    [\"You send\", esc(plan.amount + \" \" + plan.token.symbol) + \" on \" + esc(plan.l1ChainName)],\n    [\"Agent receives\", esc(plan.result)],\n    [\"Portal\", '<span class=\"mono\">' + esc(plan.portal) + \"</span>\"],\n  ].map(([k, v]) => \"<dt>\" + k + \"</dt><dd>\" + v + \"</dd>\").join(\"\");\n  $(\"privacy\").textContent = (MODE === \"hosted\" ? \"Check that the agent address matches the one your agent gave you. \" : \"\") + plan.privacy;\n}\n\nfunction row(n, cls, label, detail) {\n  return '<li class=\"' + cls + '\"><span class=\"dot\">' + (cls === \"done\" ? \"✓\" : n) + '</span><span class=\"label\">' +\n    esc(label) + '<div class=\"detail\">' + detail + \"</div></span></li>\";\n}\n\nfunction renderSteps() {\n  const explorer = plan.l1ExplorerUrl;\n  const rows = plan.steps.map((s, i) => {\n    const st = txStatus[s.id] || {};\n    const link = st.hash && explorer ? ' · <a href=\"' + esc(explorer) + \"/tx/\" + esc(st.hash) + '\" target=\"_blank\" rel=\"noopener\">view tx</a>' : \"\";\n    return row(i + 1, st.state || \"\", s.label, esc(st.text || (s.skipIf ? \"Needs your signature (skipped if already done)\" : \"Needs your signature\")) + link);\n  });\n  let n = plan.steps.length;\n  if (MODE === \"local\") {\n    const order = [\"signing\", \"waiting_l1\", \"waiting_message\", \"claiming\", \"done\"];\n    const reached = (p) => order.indexOf(phase) >= order.indexOf(p);\n    const msgCls = reached(\"claiming\") ? \"done\" : phase === \"waiting_message\" ? \"active\" : phase === \"failed\" ? \"failed\" : \"\";\n    const claimCls = phase === \"done\" ? \"done\" : phase === \"claiming\" ? \"active\" : phase === \"failed\" ? \"failed\" : \"\";\n    rows.push(row(++n, msgCls, \"Message reaches Aztec\", \"Usually a few minutes after the deposit is mined.\"));\n    rows.push(row(++n, claimCls, \"Agent claims the deposit\", \"The agent proves the claim on Aztec.\"));\n  } else {\n    const sent = txStatus.deposit && txStatus.deposit.state === \"done\";\n    rows.push(row(++n, sent ? \"active\" : \"\", \"Agent detects and claims the deposit\",\n      \"Your agent watches \" + esc(plan.l1ChainName) + \" for this deposit and claims it on Aztec, usually within a few minutes.\"));\n  }\n  $(\"steps\").innerHTML = rows.join(\"\");\n}\n\nasync function refreshLocal() {\n  const s = await api(\"/api/state\");\n  plan = s.plan;\n  phase = s.phase;\n  l2Balance = s.l2Balance;\n  serverError = s.error;\n  renderFacts();\n  renderSteps();\n  if (phase === \"done\") {\n    setStatus(\"Done. The agent's balance is \" + l2Balance + \".\", \"ok\");\n    $(\"go\").disabled = true;\n    $(\"go\").textContent = \"Funded\";\n  } else if (phase === \"failed\") {\n    setStatus(\"Claim failed: \" + (serverError || \"unknown error\") + '. Ask the agent to run \"aztec-x402 fund claim\".', \"err\");\n  } else if (phase === \"waiting_message\" || phase === \"waiting_l1\") {\n    setStatus(\"Deposit mined. Waiting for it to reach Aztec…\", \"warn\");\n  } else if (phase === \"claiming\") {\n    setStatus(\"The agent is claiming the deposit on Aztec…\", \"warn\");\n  }\n}\n\nasync function connect() {\n  if (!window.ethereum) {\n    setStatus(\"No browser wallet on this page. Install MetaMask or another browser wallet. Wallets only load on https:// and localhost pages — if you opened a plain http://<ip> link, ask your agent for the hosted link instead.\", \"err\");\n    return;\n  }\n  owner = (await eth(\"eth_requestAccounts\", []))[0];\n  const want = \"0x\" + plan.l1ChainId.toString(16);\n  if ((await eth(\"eth_chainId\", [])) !== want) {\n    await eth(\"wallet_switchEthereumChain\", [{ chainId: want }]);\n  }\n  setStatus(\"Connected \" + short(owner) + \". Sign each step in your wallet.\");\n  $(\"go\").textContent = \"Sign and send\";\n  $(\"go\").onclick = () => run().catch(fail);\n}\n\nasync function run() {\n  $(\"go\").disabled = true;\n  for (const step of plan.steps) {\n    if (txStatus[step.id] && txStatus[step.id].state === \"done\") continue;\n    for (let round = 0; round < 10; round++) {\n      txStatus[step.id] = { state: \"active\", text: \"Checking…\", hash: (txStatus[step.id] || {}).hash };\n      renderSteps();\n      if (await satisfied(step)) {\n        const previous = txStatus[step.id].hash;\n        txStatus[step.id] = round === 0\n          ? { state: \"done\", text: \"Already done — skipped\" }\n          : { state: \"done\", text: \"Confirmed\", hash: previous };\n        break;\n      }\n      txStatus[step.id] = { state: \"active\", text: \"Waiting for your signature…\" };\n      renderSteps();\n      const hash = await sendWithRetry(step);\n      txStatus[step.id] = { state: \"active\", text: \"Mining…\", hash };\n      renderSteps();\n      const receipt = await waitReceipt(hash);\n      if (receipt.status !== \"0x1\") {\n        txStatus[step.id] = { state: \"failed\", text: \"Reverted\", hash };\n        renderSteps();\n        throw new Error(\"Transaction reverted\");\n      }\n      txStatus[step.id] = { state: \"done\", text: \"Confirmed\", hash };\n      if (!step.repeat) break;\n    }\n    renderSteps();\n  }\n  $(\"go\").textContent = \"Signed\";\n  const deposit = txStatus.deposit;\n  if (MODE === \"local\") {\n    if (deposit && deposit.hash) await api(\"/api/submitted\", { l1TxHash: deposit.hash, owner });\n    submitted = true;\n    setStatus(\"Deposit sent. Waiting for your agent to pick it up…\", \"warn\");\n    await refreshLocal();\n  } else {\n    renderSteps();\n    setStatus(\"Deposit sent. Your agent will claim it on Aztec in a few minutes — you can close this page and ask it to confirm.\", \"ok\");\n  }\n}\n\nfunction fail(e) {\n  $(\"go\").disabled = false;\n  setStatus((e && e.message) || String(e), \"err\");\n}\n\n(async () => {\n  try {\n    if (MODE === \"none\") throw new Error(\"This page needs a funding link from your agent. Ask it to run `aztec-x402 fund`.\");\n    if (MODE === \"hosted\") {\n      plan = checkPlan(decodePlan(FRAGMENT));\n      renderFacts();\n      renderSteps();\n    } else {\n      await refreshLocal();\n      setInterval(() => { if (phase !== \"done\" && (submitted || phase !== \"signing\")) refreshLocal().catch(() => {}); }, 4000);\n    }\n    $(\"go\").disabled = phase !== \"signing\";\n    $(\"go\").onclick = () => connect().catch(fail);\n  } catch (e) {\n    fail(e);\n    $(\"go\").disabled = true;\n  }\n})();\n</script>\n</body>\n</html>\n";
